                    ((uint)torque_derate_torque_limit,
                     (uint)throttle_100_fueling_without_programmable_power -
                     (uint)no_load_fuel_quantity,(uint)maximum_torque_at_current_engine_speed);
  iVar1 = (uint)no_load_fuel_quantity + iVar1;
  if (iVar1 < 0) {
    iVar1 = 0;
  }
