//
// Function: mc68k_loadTpuMicrocode @ 0x00031428
//

/* Loads the TPU microcode into the TPU RAM: when TPU_TPUMCR bit 0x400 is clear it maps the TPU RAM
   at 0xFFE000 (TPURAM_TRAMBAR = 0xffe0) - copies ROM 0x30c9c to 0xFFE000-0xFFE68B - clears up to
   0xFFE6FF - copies ROM 0x31328 to 0xFFE700-0xFFE7FF - then sets TPU_TPUMCR = 0x407 (bit 0x400 =
   the TPU runs from its RAM) / TPU_CIER = 0 / TPU_TICR = 0x440. So the TPU function numbers are
   Cummins' own. No CAN register is involved (was mc68k_initInternalRamAndCAN1; PR #53 round 82) */

void mc68k_loadTpuMicrocode(void)

{
  word wVar1;
  dword *pdVar2;
  dword *pdVar3;
  dword *pdVar4;
  
  wVar1 = TPU_TPUMCR;
  if ((wVar1 & 0x400) != 0x400) {
    TPURAM_TRAMBAR = 0xffe0;
    pdVar2 = tpu_microcode_image;
    pdVar3 = (dword *)&DAT_00ffe000;
    do {
      pdVar4 = pdVar3 + 1;
      *pdVar3 = *pdVar2;
      pdVar2 = pdVar2 + 1;
      pdVar3 = pdVar4;
    } while (pdVar4 < &UNK_00ffe68c);
    do {
      pdVar2 = pdVar4 + 1;
      *pdVar4 = 0;
      pdVar4 = pdVar2;
    } while (pdVar2 < &UNK_00ffe6ff);
    pdVar3 = (dword *)tpu_microcode_entry_table;
    do {
      pdVar4 = pdVar2 + 1;
      *pdVar2 = *pdVar3;
      pdVar3 = pdVar3 + 1;
      pdVar2 = pdVar4;
    } while (pdVar4 < &UNK_00ffe7ff);
    TPU_TPUMCR = 0x407;
    TPU_CIER = 0;
    TPU_TICR = 0x440;
  }
  return;
}



//
// Function: cm550_evaluateTrendingTriggers @ 0x00031496
